local SINE_TABLE = {}
local ATAN_TABLE = {}

Angles.sins = function(yaw)
	return SINE_TABLE[((yaw % 0x10000) >> 4) + 1]
end

Angles.coss = function(yaw)
	return SINE_TABLE[(((yaw + 0x4000) % 0x10000) >> 4) + 1]
end

-- Look up the arctangent of y/x assuming the result is in range [0, 0x2000] (1/8 of a circle).
local function atan2_lookup(y, x)
    if (x == 0) then
        return ATAN_TABLE[1]
	end
	return ATAN_TABLE[(y / x * 1024 + 0.5) // 1 + 1]
end

-- Compute the angle (as a short) from (0, 0) to (x, y)
Angles.atan2s = function(y, x)
    if (x >= 0) then
        if (y >= 0) then
            if (y >= x) then
                return atan2_lookup(x, y)
			end
            return 0x4000 - atan2_lookup(y, x)
        end
		y = -y
		if (y < x) then
			return 0x4000 + atan2_lookup(y, x)
		end
		return 0x8000 - atan2_lookup(x, y)
    end
	x = -x
	if (y < 0) then
		y = -y
		if (y >= x) then
			return 0x8000 + atan2_lookup(x, y)
		end
		return 0xC000 - atan2_lookup(y, x)
	elseif (y < x) then
		return 0xC000 + atan2_lookup(y, x)
	end
	return -atan2_lookup(x, y)
end

